import { useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from "react";
import { Link, useNavigate } from "@tanstack/react-router";
import {
  Activity, ArrowDownWideNarrow, ArrowLeft, ArrowRight, AudioLines, BookMarked, BookOpen,
  BookOpenText, BookPlus, BookText, CalendarDays, Check, ChevronDown, ChevronLeft,
  ChevronRight, Clock3, Download, ExternalLink, FileUp, Flame, Heart, Headphones,
  LayoutDashboard, ListFilter, Menu, Moon, Music2, NotebookPen, Pause, Play, Plus,
  Quote as QuoteIcon, Search, Settings, Share2, Sparkles, Star, Sun, Timer, Trash2,
  TrendingUp, Trophy, X, LogOut,
} from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useAuth } from "@/lib/auth";
import { DEMO_DATA, clearLocalJournal, loadLocalJournal, loadUserJournal, makeId, saveUserJournal, type Book, type BookFormat, type Quote, type ReadingData, type ReadingStatus } from "@/lib/gildedpages-data";

const navigation = [
  { name: "Dashboard", path: "/", icon: LayoutDashboard },
  { name: "Library", path: "/library", icon: BookOpen },
  { name: "Currently Reading", path: "/currently-reading", icon: BookMarked },
  { name: "Shelves", path: "/shelves", icon: BookText },
  { name: "Goals", path: "/goals", icon: Trophy },
  { name: "Quotes", path: "/quotes", icon: QuoteIcon },
  { name: "Wishlist", path: "/wishlist", icon: Heart },
  { name: "Stats", path: "/stats", icon: Activity },
  { name: "Year in Review", path: "/year-in-review", icon: Sparkles },
  { name: "Settings", path: "/settings", icon: Settings },
] as const;
const statuses: ReadingStatus[] = ["Want to read", "Reading", "Finished", "DNF"];
const formats: BookFormat[] = ["Paperback", "Ebook", "Audiobook"];
const starterQuotes = (quotes: Quote[], books: Book[]) => quotes.map((quote) => ({ ...quote, title: books.find((book) => book.id === quote.bookId)?.title ?? "A book on your shelf", author: books.find((book) => book.id === quote.bookId)?.author ?? "" }));
const dateText = (date = new Date()) => date.toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric", year: "numeric" });
const shortDate = (value: string) => value ? new Date(`${value}T12:00:00`).toLocaleDateString("en-US", { month: "short", day: "numeric" }) : "Not set";
const greeting = () => { const hour = new Date().getHours(); return hour < 12 ? "Good morning" : hour < 17 ? "Good afternoon" : "Good evening"; };

export function GildedPagesApp({ page = "Dashboard", bookId }: { page?: string; bookId?: string }) {
  const [data, setData] = useState<ReadingData>(DEMO_DATA);
  const [ready, setReady] = useState(false);
  const [addOpen, setAddOpen] = useState(false);
  const [search, setSearch] = useState("");
  const [clock, setClock] = useState(new Date());
  const [mounted, setMounted] = useState(false);
  const navigate = useNavigate();
  useEffect(() => setMounted(true), []);
  const { user, loading: authLoading, configured, signOut } = useAuth();
  const [loadError, setLoadError] = useState<string | null>(null);
  // Load this person's journal once we know who they are. Not signed in? Go to the login page.
  useEffect(() => {
    if (authLoading || !configured) return;
    if (!user) { void navigate({ to: "/login" }); return; }
    let cancelled = false;
    setReady(false);
    setLoadError(null);
    loadUserJournal(user.id)
      .then((saved) => {
        if (cancelled) return;
        // First time on this account: bring over any journal saved in this browser, else start with the samples.
        setData(saved ?? loadLocalJournal() ?? DEMO_DATA);
        setReady(true);
      })
      .catch((error: unknown) => {
        if (!cancelled) setLoadError(error instanceof Error ? error.message : "Could not load your journal.");
      });
    return () => { cancelled = true; };
  }, [user?.id, authLoading, configured]);
  // Save changes a moment after the last edit, so we don't write on every keystroke.
  useEffect(() => {
    if (!ready || !user) return;
    const timer = window.setTimeout(() => {
      saveUserJournal(user.id, data)
        .then(() => clearLocalJournal())
        .catch(() => toast.error("Couldn't save your journal just now. Check your connection."));
    }, 800);
    return () => window.clearTimeout(timer);
  }, [data, ready, user?.id]);
  useEffect(() => {
    document.documentElement.dataset["theme"] = data.darkMode ? "dark" : "light";
    document.documentElement.dataset["fontsize"] = data.fontSize;
  }, [data.darkMode, data.fontSize]);
  useEffect(() => {
    const timer = window.setInterval(() => setClock(new Date()), 30_000);
    return () => window.clearInterval(timer);
  }, []);
  const updateBook = (id: string, change: Partial<Book>) => setData((current) => ({ ...current, books: current.books.map((book) => book.id === id ? { ...book, ...change } : book) }));
  const currentStreak = useMemo(() => calculateStreak(data.sessions), [data.sessions]);
  // The journal lives in the browser (localStorage, live clock) — render it after mount to keep SSR and client in sync.
  if (!mounted) return <div className="pw-app" aria-hidden="true" />;
  if (!configured) return <div className="pw-auth"><div className="pw-auth-card"><h1>Almost there</h1><p>Sign-in isn't set up yet. Copy <code>.env.example</code> to <code>.env</code>, add your Supabase URL and anon key, then restart the app.</p></div></div>;
  if (loadError) return <div className="pw-auth"><div className="pw-auth-card"><h1>We couldn't open your journal</h1><p>{loadError}</p><button type="button" className="pw-auth-button" onClick={() => window.location.reload()}>Try again</button></div></div>;
  if (authLoading || !user || !ready) return <div className="pw-auth"><p className="pw-auth-loading">Opening your journal…</p></div>;
  const searchMatches = search.trim() ? [
    ...data.books.filter((book) => `${book.title} ${book.author} ${book.genre} ${book.summary} ${book.review} ${book.moods.join(" ")}`.toLowerCase().includes(search.toLowerCase())).slice(0, 5).map((book) => ({ id: book.id, label: book.title, hint: book.author, type: "book" })),
    ...data.quotes.filter((quote) => `${quote.text} ${data.books.find((book) => book.id === quote.bookId)?.title}`.toLowerCase().includes(search.toLowerCase())).slice(0, 3).map((quote) => ({ id: quote.id, label: quote.text, hint: "Saved passage", type: "quote" })),
  ] : [];
  return (
    <div className="pw-app">
      <aside className="pw-sidebar">
        <Link className="pw-wordmark" to="/" aria-label="Gilded Pages home"><img className="pw-logo-img" src="/logo.png" alt="" width={42} height={42} /><span><strong>gildedpages</strong><small>YOUR READING UNIVERSE</small></span></Link>
        <div className="pw-reader-card"><div className="pw-reader-illustration" aria-hidden="true"><BookOpen size={20}/><span className="pw-illustration-dot"/></div><span><strong>Your little library</strong><small>A lovely place to be.</small></span></div>
        <nav className="pw-nav" aria-label="Main navigation">
          <span className="pw-nav-label">YOUR JOURNAL</span>
          {navigation.map(({ name, path, icon: Icon }) => (
            <Link key={path} to={path} activeProps={{ className: "pw-nav-link pw-nav-link-active" }} inactiveProps={{ className: "pw-nav-link" }}>
              <Icon size={17}/><span>{name}</span>{name === "Currently Reading" && <span className="pw-nav-count">{data.books.filter((book) => book.status === "Reading").length}</span>}
            </Link>
          ))}
        </nav>
        <div className="pw-sidebar-bottom">
          <button type="button" className="pw-sidebar-toggle" onClick={() => setData((value) => ({ ...value, darkMode: !value.darkMode }))} aria-label={data.darkMode ? "Switch to light mode" : "Switch to dark mode"}>
            {data.darkMode ? <Sun size={17}/> : <Moon size={17}/>}<span>{data.darkMode ? "Daylight" : "Evening pages"}</span><span className={`pw-toggle-track ${data.darkMode ? "pw-toggle-on" : ""}`}><span/></span>
          </button>
          <Link className="pw-streak-card" to="/goals"><span className="pw-streak-icon"><Flame size={17}/></span><span><strong>{currentStreak} day{currentStreak === 1 ? "" : "s"} in a row</strong><small>Your reading streak</small></span><ChevronRight size={15}/></Link>
          <div className="pw-reader-footer"><span className="pw-avatar">{(data.name.trim()[0] ?? "R").toUpperCase()}</span><span><strong>{data.name || "Reader"}</strong><small>Reader in residence</small></span><Link to="/settings" className="pw-quiet-icon" aria-label="Settings"><Settings size={16}/></Link><button type="button" className="pw-quiet-icon pw-signout" aria-label="Sign out" title="Sign out" onClick={() => { void signOut().then(() => navigate({ to: "/login" })); }}><LogOut size={16}/></button></div>
        </div>
      </aside>
      <main className="pw-main">
        <header className="pw-topbar">
          <div className="pw-breadcrumb"><span>Your journal</span><ChevronRight size={14}/><strong>{page}</strong></div>
          <div className="pw-topbar-right">
            <label className="pw-search"><Search size={16}/><Input aria-label="Search your books, notes, and quotes" placeholder="Find a book, a thought…" value={search} onChange={(event) => setSearch(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter" && searchMatches[0]?.type === "book") void navigate({ to: "/book/$bookId", params: { bookId: searchMatches[0].id } }); }}/><kbd>⌘ K</kbd></label>
            <span className="pw-top-date"><CalendarDays size={16}/>{mounted ? clock.toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" }) : ""}</span>
            <Button className="pw-add-top" onClick={() => setAddOpen(true)}><Plus size={17}/> <span>Add a book</span></Button>
          </div>
          {searchMatches.length > 0 && <div className="pw-search-popover" role="listbox">{searchMatches.map((match) => <button key={match.id} type="button" role="option" className="pw-search-result" onClick={() => { if (match.type === "book") void navigate({ to: "/book/$bookId", params: { bookId: match.id } }); else void navigate({ to: "/quotes" }); setSearch(""); }}><Search size={14}/><span><strong>{match.label}</strong><small>{match.hint}</small></span><ChevronRight size={14}/></button>)}</div>}
        </header>
        <div className="pw-mobile-brand"><Link className="pw-wordmark" to="/"><img className="pw-logo-img" src="/logo.png" alt="" width={42} height={42} /><span><strong>gildedpages</strong><small>YOUR READING UNIVERSE</small></span></Link><Button variant="outline" size="icon" aria-label="Add a book" onClick={() => setAddOpen(true)}><Plus/></Button></div>
        <div className="pw-content">
          {mounted && <div className="pw-welcome"><div><p className="pw-eyebrow">{dateText(clock)}</p><h1>{greeting()}, {data.name || "Reader"}<span className="pw-welcome-mark"> ✺</span></h1><p className="pw-welcome-subtitle">The world is quiet. The pages are waiting.</p></div><div className="pw-clock-note"><Clock3 size={15}/>{clock.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })}<span className="pw-clock-divider"/> A moment for yourself</div></div>}
          {page === "Dashboard" && <Dashboard data={data} streak={currentStreak} onAdd={() => setAddOpen(true)} onUpdateBook={updateBook} onBook={(id) => void navigate({ to: "/book/$bookId", params: { bookId: id } })} onData={setData}/>}
          {page === "Library" && <LibraryView data={data} onData={setData} onUpdateBook={updateBook} onBook={(id) => void navigate({ to: "/book/$bookId", params: { bookId: id } })} onAdd={() => setAddOpen(true)}/>}
          {page === "Currently Reading" && <CurrentlyReading data={data} onUpdateBook={updateBook} onBook={(id) => void navigate({ to: "/book/$bookId", params: { bookId: id } })} onData={setData}/>}
          {page === "Book journal" && <BookDetail data={data} bookId={bookId ?? ""} onData={setData} onUpdateBook={updateBook} onBack={() => void navigate({ to: "/library" })}/>}
          {page === "Shelves" && <ShelvesView data={data} onData={setData} onBook={(id) => void navigate({ to: "/book/$bookId", params: { bookId: id } })}/>}
          {page === "Goals" && <GoalsView data={data} streak={currentStreak} onData={setData} onBook={(id) => void navigate({ to: "/book/$bookId", params: { bookId: id } })}/>}
          {page === "Quotes" && <QuotesView data={data} onData={setData} onBook={(id) => void navigate({ to: "/book/$bookId", params: { bookId: id } })}/>}
          {page === "Wishlist" && <WishlistView data={data} onData={setData} onBook={(id) => void navigate({ to: "/book/$bookId", params: { bookId: id } })}/>}
          {page === "Stats" && <StatsView data={data}/>}
          {page === "Year in Review" && <YearView data={data} streak={currentStreak}/>}
          {page === "Settings" && <SettingsView data={data} onData={setData}/>}
          <footer className="pw-footer"><span>Made for your kind of quiet.</span><BookOpen size={15}/><span>Keep turning pages.</span></footer>
        </div>
        <nav className="pw-mobile-nav" aria-label="Mobile navigation">{[navigation[0], navigation[1], navigation[2], navigation[4], navigation[7], navigation[9]].map(({ name, path, icon: Icon }) => <Link key={path} to={path} activeProps={{ className: "pw-mobile-nav-item pw-mobile-nav-active" }} inactiveProps={{ className: "pw-mobile-nav-item" }}><Icon size={19}/><span>{name === "Currently Reading" ? "Reading" : name}</span></Link>)}</nav>
      </main>
      <AddBookDialog open={addOpen} onOpenChange={setAddOpen} onAdd={(book) => setData((value) => ({ ...value, books: [book, ...value.books], shelves: Array.from(new Set([...value.shelves, ...book.shelves])) }))}/>
    </div>
  );
}

function PageIntro({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <div className="pw-page-intro"><div><p className="pw-eyebrow">{eyebrow}</p><h2>{title}</h2><p>{description}</p></div>{action}</div>;
}
function SectionHeading({ eyebrow, title, to, linkText = "See all" }: { eyebrow?: string; title: string; to?: string; linkText?: string }) {
  return <div className="pw-section-heading"><div>{eyebrow && <p className="pw-eyebrow">{eyebrow}</p>}<h3>{title}</h3></div>{to && <Link className="pw-text-link" to={to}>{linkText}<ArrowRight size={15}/></Link>}</div>;
}
function StatCard({ icon: Icon, eyebrow, value, note, modifier = "" }: { icon: typeof BookOpen; eyebrow: string; value: string | number; note: string; modifier?: string }) {
  return <div className={`pw-stat-card ${modifier}`}><span className="pw-stat-icon"><Icon size={18}/></span><span className="pw-stat-label">{eyebrow}</span><strong className="pw-stat-value">{value}</strong><span className="pw-stat-note">{note}</span></div>;
}
function Cover({ book, className = "", onClick }: { book: Book; className?: string; onClick?: () => void }) {
  return <button type="button" className={`pw-cover ${className} pw-cover-${book.color}`} onClick={onClick} aria-label={`Open ${book.title} by ${book.author}`}><img loading="lazy" src={book.cover} alt={`Cover of ${book.title}`} onError={(event) => { event.currentTarget.style.visibility = "hidden"; }} /><span className="pw-cover-label"><span className="pw-cover-author">{book.author}</span><strong>{book.title}</strong><span className="pw-cover-decoration"><BookOpen size={19}/></span></span>{book.status === "Finished" && <span className="pw-cover-finished"><Check size={11}/> Read</span>}</button>;
}
function BookTile({ book, onClick, compact = false }: { book: Book; onClick: () => void; compact?: boolean }) {
  return <article className={`pw-book-tile ${compact ? "pw-book-tile-compact" : ""}`}><Cover book={book} onClick={onClick}/><div className="pw-book-tile-copy"><button type="button" className="pw-book-title" onClick={onClick}>{book.title}</button><span>{book.author}</span>{book.rating > 0 && <span className="pw-stars" aria-label={`Rated ${book.rating} out of 5`}><Star size={12}/>{"★".repeat(book.rating)}<span className="pw-rating-number">{book.rating.toFixed(1)}</span></span>}<span className={`pw-status pw-status-${book.status.toLowerCase().replaceAll(" ", "-")}`}>{book.status}</span></div></article>;
}
function ProgressBar({ current, total }: { current: number; total: number }) {
  const percentage = total > 0 ? Math.min(100, Math.round(current / total * 100)) : 0;
  return <div className="pw-progress"><div className="pw-progress-track"><span style={{ width: `${percentage}%` }}/></div><span className="pw-progress-number">{percentage}%</span></div>;
}
function GoalRing({ value, total, label, size = "large" }: { value: number; total: number; label: string; size?: "large" | "small" }) {
  const percentage = total ? Math.min(100, Math.round(value / total * 100)) : 0;
  const radius = size === "large" ? 49 : 36;
  const circumference = 2 * Math.PI * radius;
  return <div className={`pw-goal-ring pw-goal-ring-${size}`} role="img" aria-label={`${label}: ${value} of ${total}, ${percentage}%`}><svg viewBox="0 0 120 120" aria-hidden="true"><circle className="pw-ring-track" cx="60" cy="60" r={radius}/><circle className="pw-ring-progress" cx="60" cy="60" r={radius} strokeDasharray={circumference} strokeDashoffset={circumference * (1 - percentage / 100)}/></svg><span className="pw-ring-copy"><strong>{value}<span>/{total}</span></strong><small>{label}</small></span></div>;
}
function Dashboard({ data, streak, onAdd, onUpdateBook, onBook, onData }: { data: ReadingData; streak: number; onAdd: () => void; onUpdateBook: (id: string, change: Partial<Book>) => void; onBook: (id: string) => void; onData: (data: ReadingData) => void }) {
  const [monthOffset, setMonthOffset] = useState(0);
  const [timerBook, setTimerBook] = useState<string | null>(null);
  const finished = data.books.filter((book) => book.status === "Finished");
  const reading = data.books.filter((book) => book.status === "Reading");
  const pages = data.sessions.reduce((total, session) => total + session.pages, 0);
  const averageRating = finished.length ? (finished.reduce((total, book) => total + book.rating, 0) / finished.length).toFixed(1) : "—";
  const targetDate = new Date(); targetDate.setDate(1); targetDate.setMonth(targetDate.getMonth() + monthOffset);
  const targetYear = targetDate.getFullYear(), targetMonth = targetDate.getMonth(), monthName = targetDate.toLocaleDateString("en-US", { month: "long", year: "numeric" });
  const firstDay = new Date(targetYear, targetMonth, 1).getDay();
  const daysThisMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
  const readingDays = new Set(data.sessions.filter((session) => { const d = new Date(`${session.date}T12:00:00`); return d.getFullYear() === targetYear && d.getMonth() === targetMonth; }).map((session) => new Date(`${session.date}T12:00:00`).getDate()));
  const quote = data.quotes[new Date().getDay() % Math.max(1, data.quotes.length)];
  const orderedWishlist = data.books.filter((book) => book.status === "Want to read");
  const monthReadingDays = readingDays.size;
  return <>
    <section className="pw-stats-strip" aria-label="Your reading at a glance"><StatCard icon={BookOpenText} eyebrow="Books finished" value={finished.length} note="This year"/><StatCard icon={BookMarked} eyebrow="Pages turned" value={pages.toLocaleString()} note="In your logged sessions" modifier="pw-stat-terracotta"/><StatCard icon={Flame} eyebrow="Current streak" value={`${streak} days`} note={streak ? "You're on a roll" : "Pick up a book today"} modifier="pw-stat-gold"/><StatCard icon={Star} eyebrow="Average rating" value={averageRating} note="Stars from the heart" modifier="pw-stat-ink"/></section>
    <div className="pw-dashboard-top-grid"><section className="pw-panel pw-reading-panel"><div className="pw-panel-heading"><div><p className="pw-eyebrow">A story in progress</p><h3>On your nightstand</h3></div><Link className="pw-text-link" to="/currently-reading">All reading<ArrowRight size={15}/></Link></div>{reading.length ? <div className="pw-reading-books">{reading.map((book) => <article className="pw-reading-item" key={book.id}><Cover book={book} className="pw-reading-cover" onClick={() => onBook(book.id)}/><div className="pw-reading-detail"><button className="pw-book-title" type="button" onClick={() => onBook(book.id)}>{book.title}</button><span className="pw-reading-author">{book.author}</span><div className="pw-reading-page-label">Page <strong>{book.progress}</strong> of {book.pages}<span>{book.pages ? Math.round(book.progress / book.pages * 100) : 0}%</span></div><ProgressBar current={book.progress} total={book.pages}/><label className="pw-slider-label" htmlFor={`page-${book.id}`}>Update your page</label><input aria-label={`Update reading progress for ${book.title}`} className="pw-page-slider" type="range" min="0" max={book.pages} value={book.progress} id={`page-${book.id}`} onChange={(event) => { const newProgress = Number(event.target.value); onUpdateBook(book.id, { progress: newProgress, ...(newProgress >= book.pages ? { status: "Finished" as const, finished: new Date().toISOString().slice(0, 10), rating: book.rating || 5 } : {}) }); if (newProgress >= book.pages) toast.success("Finished! A whole new world read."); }}/><Button variant="outline" size="sm" className="pw-timer-button" onClick={() => setTimerBook(book.id)}><Timer size={15}/>Read a little</Button></div></article>)}</div> : <EmptyState icon={BookOpen} title="A little room for a new story" action={<Button onClick={onAdd}><Plus size={16}/>Add a book</Button>}/>}</section>
    <section className="pw-panel pw-goal-panel"><div className="pw-panel-heading"><div><p className="pw-eyebrow">Steady as she goes</p><h3>A year of reading</h3></div><Link to="/goals" className="pw-quiet-icon" aria-label="Adjust reading goals"><ArrowRight size={17}/></Link></div><div className="pw-goal-display"><GoalRing value={finished.length} total={data.annualGoal} label="books read"/><div className="pw-goal-copy"><strong>One chapter<br/>at a time.</strong><span>{Math.max(0, data.annualGoal - finished.length)} more to reach your yearly goal</span></div></div><div className="pw-monthly-goal"><span><span className="pw-mini-ring-mark"><BookMarked size={14}/></span>This month</span><strong>{Math.min(monthlyFinished(data), data.monthlyGoal)} of {data.monthlyGoal} books</strong><ProgressBar current={monthlyFinished(data)} total={data.monthlyGoal}/></div><p className="pw-goal-note"><Sparkles size={13}/> Your next favorite is just a page away.</p></section></div>
    <div className="pw-dashboard-mid-grid"><section className="pw-panel pw-calendar-panel"><div className="pw-panel-heading"><div><p className="pw-eyebrow">A moment, made for you</p><h3>A month in pages</h3></div><div className="pw-month-controls"><Button variant="ghost" size="icon" aria-label="Previous month" onClick={() => setMonthOffset((value) => value - 1)}><ChevronLeft/></Button><span>{monthName}</span><Button variant="ghost" size="icon" aria-label="Next month" onClick={() => setMonthOffset((value) => value + 1)}><ChevronRight/></Button></div></div><div className="pw-calendar-grid" aria-label={`Reading calendar for ${monthName}`}>{["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map((weekday) => <span className="pw-calendar-weekday" key={weekday}>{weekday}</span>)}{Array.from({ length: firstDay }, (_, index) => <span key={`blank-${index}`}/>)}{Array.from({ length: daysThisMonth }, (_, index) => { const dayNumber = index + 1, isToday = monthOffset === 0 && dayNumber === new Date().getDate(); return <span key={dayNumber} className={`pw-calendar-day ${readingDays.has(dayNumber) ? "pw-calendar-read" : ""} ${isToday ? "pw-calendar-today" : ""}`} title={readingDays.has(dayNumber) ? "A day spent reading" : undefined}>{dayNumber}{readingDays.has(dayNumber) && <BookOpen size={9}/>}</span>; })}</div><p className="pw-calendar-footer"><BookOpen size={13}/><span><strong>{monthReadingDays} reading days</strong> this month</span><span className="pw-calendar-legend"/></p></section>
    <section className="pw-panel pw-heatmap-panel"><div className="pw-panel-heading"><div><p className="pw-eyebrow">Small moments add up</p><h3>The reading ritual</h3></div><span className="pw-heatmap-total"><strong>{data.sessions.filter((session) => session.minutes > 0).length}</strong> sessions</span></div><ReadingHeatmap sessions={data.sessions}/><div className="pw-heatmap-legend"><span>Less</span>{[0, 1, 2, 3, 4].map((item) => <span key={item} className={`pw-heat-swatch pw-heat-${item}`}/>)}<span>More</span><span className="pw-heatmap-period">The past six months</span></div><p className="pw-heatmap-message"><Flame size={14}/>Every page counts. You have shown up {Math.max(streak, 1)} time{streak === 1 ? "" : "s"} in a row.</p></section></div>
    <div className="pw-dashboard-bottom-grid"><section className="pw-quote-paper"><span className="pw-paper-tape"/><span className="pw-handwritten">a thought to keep</span>{quote ? <><QuoteIcon className="pw-quote-mark" size={19}/><blockquote>{quote.text}</blockquote><p>— {data.books.find((book) => book.id === quote.bookId)?.title ?? "Your journal"}<span>{quote.page ? `, p. ${quote.page}` : ""}</span></p><Button className="pw-new-quote" variant="ghost" size="sm" onClick={() => undefined} aria-label="Browse your saved quotes">Your collected lines<ArrowRight size={14}/></Button></> : <EmptyState icon={QuoteIcon} title="A few words worth keeping"/>}</section>
    <section className="pw-panel pw-next-panel"><div className="pw-panel-heading"><div><p className="pw-eyebrow">For the chapters ahead</p><h3>In your future</h3></div><Link to="/wishlist" className="pw-text-link">Your wishlist<ArrowRight size={15}/></Link></div><div className="pw-up-next-covers">{orderedWishlist.slice(0, 4).map((book) => <Cover key={book.id} book={book} className="pw-wishlist-cover" onClick={() => onBook(book.id)}/>) }{orderedWishlist.length === 0 && <p>Your next chapter is unwritten. <button type="button" className="pw-inline-link" onClick={onAdd}>Add a book</button></p>}</div></section>
    <section className="pw-panel pw-player-panel"><div className="pw-player-icon"><Headphones size={19}/></div><div className="pw-player-copy"><p className="pw-eyebrow">A soundtrack for slower pages</p><h3>Reading mood</h3><span>{data.spotify ? "Your reading playlist is ready." : "Some music for your next chapter."}</span></div>{data.spotify ? <a className="pw-player-link" href={spotifyEmbed(data.spotify)} target="_blank" rel="noreferrer" aria-label="Open reading playlist"><ExternalLink size={16}/></a> : <Link className="pw-player-link" to="/settings" aria-label="Add a reading playlist"><Plus size={18}/></Link>}</section></div>
    <QuickLinks data={data} onData={onData}/><TimerDialog book={data.books.find((book) => book.id === timerBook) ?? null} onClose={() => setTimerBook(null)} onSave={(bookId, minutes, sessionPages) => { const session = { id: makeId(), bookId, date: new Date().toISOString().slice(0, 10), minutes, pages: sessionPages }; onData({ ...data, sessions: [session, ...data.sessions] }); const book = data.books.find((item) => item.id === bookId); if (book) onUpdateBook(bookId, { progress: Math.min(book.pages, book.progress + sessionPages) }); toast.success(`${sessionPages} pages tucked away. What a lovely session.`); }}/>
  </>;
}

function ReadingHeatmap({ sessions }: { sessions: ReadingData["sessions"] }) {
  const totals = new Map<string, number>(); sessions.forEach((session) => totals.set(session.date, (totals.get(session.date) ?? 0) + session.pages));
  const cells = Array.from({ length: 182 }, (_, index) => { const date = new Date(); date.setDate(date.getDate() - (181 - index)); const key = date.toISOString().slice(0, 10); const pages = totals.get(key) ?? 0; return { date: key, pages, level: pages === 0 ? 0 : pages < 16 ? 1 : pages < 35 ? 2 : pages < 60 ? 3 : 4 }; });
  return <div className="pw-heatmap"><div className="pw-heatmap-months"><span>6 mo ago</span><span>5 mo</span><span>4 mo</span><span>3 mo</span><span>2 mo</span><span>This month</span></div><div className="pw-heatmap-cells">{cells.map((cell) => <span key={cell.date} className={`pw-heat-swatch pw-heat-${cell.level}`} title={`${cell.date}: ${cell.pages} pages`} aria-label={`${cell.date}, ${cell.pages} pages`}/>)}</div></div>;
}
function monthlyFinished(data: ReadingData) { const now = new Date(); return data.books.filter((book) => book.status === "Finished" && book.finished && new Date(`${book.finished}T12:00:00`).getMonth() === now.getMonth() && new Date(`${book.finished}T12:00:00`).getFullYear() === now.getFullYear()).length; }
function calculateStreak(sessions: ReadingData["sessions"]) {
  const readingDates = new Set(sessions.filter((session) => session.minutes > 0 || session.pages > 0).map((session) => session.date));
  let cursor = new Date(); cursor.setHours(0, 0, 0, 0);
  const todayKey = cursor.toISOString().slice(0, 10);
  if (!readingDates.has(todayKey)) cursor.setDate(cursor.getDate() - 1);
  let count = 0;
  while (readingDates.has(cursor.toISOString().slice(0, 10))) { count++; cursor.setDate(cursor.getDate() - 1); }
  return count;
}
function EmptyState({ icon: Icon, title, action }: { icon: typeof BookOpen; title: string; action?: ReactNode }) { return <div className="pw-empty"><Icon size={24}/><strong>{title}</strong>{action}</div>; }

function AddBookDialog({ open, onOpenChange, onAdd }: { open: boolean; onOpenChange: (open: boolean) => void; onAdd: (book: Book) => void }) {
  const [onlineSearch, setOnlineSearch] = useState("");
  const [suggestions, setSuggestions] = useState<{ title: string; author: string; pages: number; cover: string; key: string }[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchError, setSearchError] = useState("");
  const [title, setTitle] = useState("");
  const [author, setAuthor] = useState("");
  const [pages, setPages] = useState("300");
  const [status, setStatus] = useState<ReadingStatus>("Want to read");
  const [format, setFormat] = useState<BookFormat>("Paperback");
  const [genre, setGenre] = useState("Literary fiction");
  const [rating, setRating] = useState("0");
  const [cover, setCover] = useState("");
  const [spotify, setSpotify] = useState("");
  const [shelves, setShelves] = useState("");
  useEffect(() => { if (!open) { setOnlineSearch(""); setSuggestions([]); setSearchError(""); } }, [open]);
  const findOnline = async (event: FormEvent) => { event.preventDefault(); if (!onlineSearch.trim()) return; setLoading(true); setSearchError(""); setSuggestions([]); try { const response = await fetch(`https://openlibrary.org/search.json?q=${encodeURIComponent(onlineSearch)}&limit=6`); if (!response.ok) throw new Error("Search is taking a little break. Try again in a moment."); const result = await response.json() as { docs?: { key?: string; title?: string; author_name?: string[]; number_of_pages_median?: number; cover_i?: number }[] }; const books = (result.docs ?? []).filter((book) => book.title).map((book) => ({ key: book.key ?? makeId(), title: book.title ?? "Untitled", author: book.author_name?.[0] ?? "Unknown author", pages: book.number_of_pages_median ?? 300, cover: book.cover_i ? `https://covers.openlibrary.org/b/id/${book.cover_i}-L.jpg` : "" })); setSuggestions(books); if (!books.length) setSearchError("No matches just yet. You can add this book by hand."); } catch (error) { setSearchError(error instanceof Error ? error.message : "We couldn't reach the book shelves. Try adding it by hand."); } finally { setLoading(false); } };
  const selectSuggestion = (book: typeof suggestions[number]) => { setTitle(book.title); setAuthor(book.author); setPages(String(book.pages)); setCover(book.cover); setSuggestions([]); };
  const submit = (event: FormEvent) => { event.preventDefault(); if (!title.trim() || !author.trim()) { toast.error("Please add a title and an author."); return; } const startDate = status === "Reading" ? new Date().toISOString().slice(0, 10) : ""; onAdd({ id: makeId(), title: title.trim(), author: author.trim(), genre: genre.trim() || "Unsorted", pages: Math.max(1, Number(pages) || 300), progress: 0, cover: cover.trim(), color: ["fern", "blue", "ochre", "rose", "sage"][Math.floor(Math.random() * 5)] ?? "fern", status, format, rating: Number(rating), started: startDate, finished: "", moods: [], shelves: shelves.split(",").map((shelf) => shelf.trim()).filter(Boolean), tropes: [], spotify: spotify.trim(), summary: "", review: "", reread: false }); setTitle(""); setAuthor(""); setPages("300"); setRating("0"); setCover(""); setSpotify(""); onOpenChange(false); toast.success(`“${title}” is on your shelves.`); };
  if (!open) return null;
  return <div className="pw-modal-backdrop" role="presentation" onClick={(event) => { if (event.target === event.currentTarget) onOpenChange(false); }}><section className="pw-modal" role="dialog" aria-modal="true" aria-labelledby="pw-add-title"><div className="pw-modal-heading"><span className="pw-modal-icon"><BookPlus size={21}/></span><div><p className="pw-eyebrow">A new arrival</p><h2 id="pw-add-title">Add a book</h2><p>Leave a little space for your next story.</p></div><Button variant="ghost" size="icon" onClick={() => onOpenChange(false)} aria-label="Close"><X/></Button></div>
    <form className="pw-add-form" onSubmit={submit}><div className="pw-online-search"><label className="pw-field-label" htmlFor="pw-online-search">Find it in the library</label><div className="pw-search-inline"><Input id="pw-online-search" value={onlineSearch} onChange={(event) => setOnlineSearch(event.target.value)} placeholder="Search book title or author…"/><Button type="button" variant="secondary" disabled={loading} onClick={(event) => { const form = event.currentTarget.closest(".pw-online-search"); if (form) void findOnline({ preventDefault: () => undefined } as FormEvent); }}>{loading ? "Looking…" : <><Search size={15}/>Search online</>}</Button></div>{searchError && <p className="pw-form-notice">{searchError}</p>}{suggestions.length > 0 && <div className="pw-suggestions">{suggestions.map((suggestion) => <button type="button" className="pw-suggestion" key={suggestion.key} onClick={() => selectSuggestion(suggestion)}>{suggestion.cover ? <img src={suggestion.cover} alt="" loading="lazy"/> : <BookOpen size={17}/>}<span><strong>{suggestion.title}</strong><small>{suggestion.author} · {suggestion.pages} pages</small></span><Plus size={15}/></button>)}</div>}</div>
    <div className="pw-form-grid"><label className="pw-form-field pw-field-full"><span className="pw-field-label">Title *</span><Input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="A story's title" required/></label><label className="pw-form-field pw-field-full"><span className="pw-field-label">Author *</span><Input value={author} onChange={(event) => setAuthor(event.target.value)} placeholder="The person who wrote it" required/></label><label className="pw-form-field"><span className="pw-field-label">Genre</span><Input value={genre} onChange={(event) => setGenre(event.target.value)} placeholder="Literary fiction"/></label><label className="pw-form-field"><span className="pw-field-label">Total pages</span><Input type="number" min="1" value={pages} onChange={(event) => setPages(event.target.value)}/></label><label className="pw-form-field"><span className="pw-field-label">Reading status</span><select className="pw-select" value={status} onChange={(event) => setStatus(event.target.value as ReadingStatus)}>{statuses.map((item) => <option key={item}>{item}</option>)}</select></label><label className="pw-form-field"><span className="pw-field-label">Format</span><select className="pw-select" value={format} onChange={(event) => setFormat(event.target.value as BookFormat)}>{formats.map((item) => <option key={item}>{item}</option>)}</select></label><label className="pw-form-field"><span className="pw-field-label">Cover image link</span><Input type="url" value={cover} onChange={(event) => setCover(event.target.value)} placeholder="https://…"/></label><label className="pw-form-field"><span className="pw-field-label">Reading mood</span><Input placeholder="Cosy, thought-provoking…" onChange={(event) => { (event.currentTarget as HTMLInputElement).dataset['moods'] = event.currentTarget.value; }}/></label><label className="pw-form-field"><span className="pw-field-label">Star rating</span><select className="pw-select" value={rating} onChange={(event) => setRating(event.target.value)}>{[0, 1, 2, 3, 4, 5].map((star) => <option key={star} value={star}>{star === 0 ? "Not rated yet" : `${star} out of 5 stars`}</option>)}</select></label><label className="pw-form-field"><span className="pw-field-label">A shelf to call home</span><Input placeholder="Fiction, Summer reads…" value={shelves} onChange={(event) => setShelves(event.target.value)}/></label><label className="pw-form-field pw-field-full"><span className="pw-field-label">A soundtrack, if there is one</span><Input type="url" value={spotify} onChange={(event) => setSpotify(event.target.value)} placeholder="Spotify playlist or audiobook link"/></label></div><div className="pw-modal-actions"><Button type="button" variant="ghost" onClick={() => onOpenChange(false)}>Maybe later</Button><Button type="submit"><BookPlus size={16}/>Add to my library</Button></div></form></section></div>;
}
function LibraryView({ data, onData, onUpdateBook, onBook, onAdd }: { data: ReadingData; onData: (data: ReadingData) => void; onUpdateBook: (id: string, change: Partial<Book>) => void; onBook: (id: string) => void; onAdd: () => void }) {
  const [filter, setFilter] = useState("All books"); const [genre, setGenre] = useState("All genres"); const [format, setFormat] = useState("All formats"); const [sort, setSort] = useState("Recently added"); const [mode, setMode] = useState("Grid"); const [search, setSearch] = useState("");
  const filtered = useMemo(() => data.books.filter((book) => (filter === "All books" || book.status === filter) && (genre === "All genres" || book.genre === genre) && (format === "All formats" || book.format === format) && `${book.title} ${book.author} ${book.moods.join(" ")}`.toLowerCase().includes(search.toLowerCase())).sort((a, b) => sort === "Title" ? a.title.localeCompare(b.title) : sort === "Highest rated" ? b.rating - a.rating : sort === "Longest first" ? b.pages - a.pages : 0), [data.books, filter, genre, format, sort, search]);
  const genres = Array.from(new Set(data.books.map((book) => book.genre)));
  return <><PageIntro eyebrow="A life in books" title="Your reading room" description="All the stories that found their way to you." action={<Button onClick={onAdd}><Plus size={16}/>Add a book</Button>}/><div className="pw-library-tally"><strong>{data.books.length}</strong> books, <span>{data.books.filter((book) => book.status === "Finished").length} finished</span><span className="pw-tally-divider"/><span>{data.books.filter((book) => book.status === "Reading").length} in progress</span></div><section className="pw-library-toolbar" aria-label="Library filters"><label className="pw-library-search"><Search size={15}/><Input aria-label="Search your library" placeholder="Search your collection…" value={search} onChange={(event) => setSearch(event.target.value)}/></label><select aria-label="Filter by status" className="pw-select" value={filter} onChange={(event) => setFilter(event.target.value)}>{["All books", ...statuses].map((value) => <option key={value}>{value}</option>)}</select><select aria-label="Filter by genre" className="pw-select" value={genre} onChange={(event) => setGenre(event.target.value)}><option>All genres</option>{genres.map((value) => <option key={value}>{value}</option>)}</select><select aria-label="Filter by format" className="pw-select" value={format} onChange={(event) => setFormat(event.target.value)}>{["All formats", ...formats].map((value) => <option key={value}>{value}</option>)}</select><select aria-label="Sort library" className="pw-select pw-sort-select" value={sort} onChange={(event) => setSort(event.target.value)}>{["Recently added", "Title", "Highest rated", "Longest first"].map((value) => <option key={value}>{value}</option>)}</select><div className="pw-view-toggle" aria-label="Choose a bookshelf view">{["Grid", "List", "Shelf"].map((view) => <button type="button" key={view} className={mode === view ? "pw-view-active" : ""} onClick={() => setMode(view)} aria-pressed={mode === view}>{view}</button>)}</div></section>{filtered.length === 0 ? <EmptyState icon={Search} title="Nothing in these shelves just yet" action={<Button variant="outline" onClick={() => { setFilter("All books"); setGenre("All genres"); setFormat("All formats"); setSearch(""); }}>Show every book</Button>}/> : mode === "Grid" ? <div className="pw-book-grid">{filtered.map((book) => <BookTile key={book.id} book={book} onClick={() => onBook(book.id)}/>)}</div> : mode === "List" ? <div className="pw-table-wrap"><table className="pw-library-table"><thead><tr><th>Title</th><th>Genre</th><th>Status</th><th>Pages</th><th>Rating</th><th>Format</th></tr></thead><tbody>{filtered.map((book) => <tr key={book.id} onClick={() => onBook(book.id)}><td><strong>{book.title}</strong><span>{book.author}</span></td><td>{book.genre}</td><td><span className={`pw-status pw-status-${book.status.toLowerCase().replaceAll(" ", "-")}`}>{book.status}</span></td><td>{book.progress}/{book.pages}</td><td>{book.rating ? `★ ${book.rating}` : "—"}</td><td>{book.format}</td></tr>)}</tbody></table></div> : <div className="pw-bookshelf-view"><div className="pw-bookshelf-grid">{filtered.map((book) => <button type="button" className={`pw-spine pw-cover-${book.color}`} key={book.id} title={`${book.title} — ${book.author}`} onClick={() => onBook(book.id)}><span>{book.title}</span><small>{book.author}</small></button>)}</div><div className="pw-shelf-wood"><span/></div><div className="pw-bookshelf-grid">{data.books.filter((book) => book.status !== "Want to read").slice(0, 4).map((book) => <button type="button" className={`pw-spine pw-cover-${book.color}`} key={book.id} title={book.title} onClick={() => onBook(book.id)}><span>{book.title}</span><small>{book.author}</small></button>)}</div><div className="pw-shelf-wood"><span/></div></div>}<p className="pw-library-footer"><ListFilter size={14}/>{filtered.length} {filtered.length === 1 ? "book" : "books"} finding their home</p></>;
}

function CurrentlyReading({ data, onUpdateBook, onBook, onData }: { data: ReadingData; onUpdateBook: (id: string, change: Partial<Book>) => void; onBook: (id: string) => void; onData: (data: ReadingData) => void }) {
  const books = data.books.filter((book) => book.status === "Reading");
  const [timerBook, setTimerBook] = useState<Book | null>(null);
  return <><PageIntro eyebrow="The books beside you" title="Currently reading" description="One quiet chapter at a time. Follow your progress, pick up where you left off, or settle in for a reading session."/>{books.length === 0 ? <EmptyState icon={BookOpen} title="Your next story is waiting on a shelf." action={<Button asChild><Link to="/library">Visit your library</Link></Button>}/> : <div className="pw-currently-list">{books.map((book) => <article className="pw-currently-item pw-panel" key={book.id}><Cover book={book} className="pw-currently-cover" onClick={() => onBook(book.id)}/><div className="pw-currently-copy"><p className="pw-eyebrow">{book.genre} · {book.format}</p><button type="button" onClick={() => onBook(book.id)} className="pw-book-title pw-currently-title">{book.title}</button><span className="pw-reading-author">by {book.author}</span><p className="pw-currently-blurb">{book.summary || "Your next little stretch of the story is right where you left it."}</p><p className="pw-reading-page-label">Page <strong>{book.progress}</strong> of {book.pages}<span>{book.pages ? Math.round(book.progress / book.pages * 100) : 0}%</span></p><ProgressBar current={book.progress} total={book.pages}/><label className="pw-field-label" htmlFor={`current-${book.id}`}>Update your page</label><input type="range" min="0" max={book.pages} value={book.progress} id={`current-${book.id}`} className="pw-page-slider" aria-label={`Update page for ${book.title}`} onChange={(event) => { const progress = Number(event.target.value); onUpdateBook(book.id, { progress, ...(progress >= book.pages ? { status: "Finished" as const, finished: new Date().toISOString().slice(0, 10), rating: book.rating || 5 } : {}) }); }}/><div className="pw-current-actions"><Button onClick={() => setTimerBook(book)}><Timer size={15}/>Start a reading session</Button><Button variant="outline" onClick={() => onBook(book.id)}><NotebookPen size={15}/>Book journal</Button></div></div></article>)}</div>}<TimerDialog book={timerBook} onClose={() => setTimerBook(null)} onSave={(bookId, minutes, pages) => { const session = { id: makeId(), bookId, date: new Date().toISOString().slice(0, 10), minutes, pages }; onData({ ...data, sessions: [session, ...data.sessions] }); const book = data.books.find((item) => item.id === bookId); if (book) onUpdateBook(bookId, { progress: Math.min(book.pages, book.progress + pages) }); toast.success(`${pages} pages tucked away. What a lovely session.`); }}/></>;
}

function BookDetail({ data, bookId, onData, onUpdateBook, onBack }: { data: ReadingData; bookId: string; onData: (data: ReadingData) => void; onUpdateBook: (id: string, change: Partial<Book>) => void; onBack: () => void }) {
  const book = data.books.find((item) => item.id === bookId);
  const [noteChapter, setNoteChapter] = useState(""); const [noteText, setNoteText] = useState(""); const [quoteText, setQuoteText] = useState(""); const [quotePage, setQuotePage] = useState("");
  if (!book) return <><PageIntro eyebrow="A missing book" title="Not on this shelf" description="We couldn't find that book in your journal."/><Button variant="outline" onClick={onBack}><ArrowLeft size={15}/>Back to your library</Button></>;
  const bookQuotes = data.quotes.filter((quote) => quote.bookId === book.id);
  const addNote = (event: FormEvent) => { event.preventDefault(); if (!noteText.trim()) return; const notes = book.notes ?? []; onUpdateBook(book.id, { notes: [{ chapter: noteChapter.trim() || `Chapter ${notes.length + 1}`, text: noteText.trim() }, ...notes] }); setNoteChapter(""); setNoteText(""); toast.success("A little note, saved for later."); };
  const removeBook = () => { if (!window.confirm(`Remove “${book.title}” and its notes from your library?`)) return; onData({ ...data, books: data.books.filter((item) => item.id !== book.id), quotes: data.quotes.filter((quote) => quote.bookId !== book.id), sessions: data.sessions.filter((session) => session.bookId !== book.id) }); toast.success("Book removed from your library."); onBack(); };
  const addQuote = (event: FormEvent) => { event.preventDefault(); if (!quoteText.trim()) return; onData({ ...data, quotes: [{ id: makeId(), bookId: book.id, text: quoteText.trim(), page: Number(quotePage) || 0, favorite: false }, ...data.quotes] }); setQuoteText(""); setQuotePage(""); toast.success("Saved among your favorite lines."); };
  return <><button type="button" className="pw-back-link" onClick={onBack}><ArrowLeft size={15}/> Back to the library</button><PageIntro eyebrow="A journal, just for this story" title={book.title} description={`A closer look at your time with ${book.author}.`}/><div className="pw-detail-layout"><div className="pw-detail-book-aside"><Cover book={book} className="pw-detail-cover"/><div className="pw-rating-picker"><span>Your stars, your way</span><div aria-label="Rate this book">{[1, 2, 3, 4, 5].map((value) => <button type="button" key={value} className={`pw-star-button ${book.rating >= value ? "pw-star-filled" : ""}`} onClick={() => onUpdateBook(book.id, { rating: value })} aria-label={`Rate ${value} out of 5`}><Star size={24} fill="currentColor"/></button>)}</div></div><section className="pw-panel pw-book-facts"><p className="pw-eyebrow">Between the covers</p>{[["Written by", book.author], ["Genre", book.genre], ["Pages", String(book.pages)], ["Began on", shortDate(book.started)], ["Finished on", book.finished ? shortDate(book.finished) : "Still reading"], ["Format", book.format]].map(([label, value]) => <div className="pw-fact-row" key={label}><span>{label}</span><strong>{value}</strong></div>)}<label className="pw-field-label" htmlFor="pw-detail-status">Your reading status</label><select id="pw-detail-status" className="pw-select" value={book.status} onChange={(event) => { const status = event.target.value as ReadingStatus; onUpdateBook(book.id, { status, ...(status === "Finished" && !book.finished ? { finished: new Date().toISOString().slice(0, 10), progress: book.pages } : {}) }); }}><option>Want to read</option><option>Reading</option><option>Finished</option><option>DNF</option></select></section><div className="pw-detail-actions"><Button variant="outline" onClick={() => window.print()}><Share2 size={15}/>Print journal</Button><Button variant="outline" className="pw-delete-button" onClick={removeBook}><Trash2 size={15}/>Remove book</Button></div></div><div className="pw-detail-main"><section className="pw-panel pw-detail-progress"><div className="pw-panel-heading"><div><p className="pw-eyebrow">Your reading, one page at a time</p><h3>Where you left off</h3></div><span className="pw-detail-percent">{book.pages ? Math.round(book.progress / book.pages * 100) : 0}%</span></div><p className="pw-reading-page-label">Page <strong>{book.progress}</strong> of {book.pages}</p><ProgressBar current={book.progress} total={book.pages}/><input aria-label={`Update progress on ${book.title}`} type="range" className="pw-page-slider" min="0" max={book.pages} value={book.progress} onChange={(event) => { const progress = Number(event.target.value); onUpdateBook(book.id, { progress, ...(progress >= book.pages ? { status: "Finished", finished: new Date().toISOString().slice(0, 10) } : { status: "Reading" }) }); }}/></section><section className="pw-panel"><div className="pw-panel-heading"><div><p className="pw-eyebrow">The heart of the story</p><h3>A little summary</h3></div><NotebookPen size={17}/></div><Textarea className="pw-editor-textarea" aria-label="Book summary" placeholder="What is this story about? A few thoughts in your own words…" value={book.summary} onChange={(event) => onUpdateBook(book.id, { summary: event.target.value })}/><span className="pw-saved-note"><Check size={13}/>Saved as you write</span></section><section className="pw-panel"><div className="pw-panel-heading"><div><p className="pw-eyebrow">Your honest impression</p><h3>A note to your future self</h3></div><span className="pw-handwritten">margin note</span></div><Textarea className="pw-editor-textarea pw-review-area" aria-label="Your review" placeholder="What will you remember about this book? The moment that made you smile, think, or turn just one more page…" value={book.review} onChange={(event) => onUpdateBook(book.id, { review: event.target.value })}/><div className="pw-reread-row"><span>Would you wander through it again?</span><button type="button" className={`pw-reread-toggle ${book.reread ? "pw-reread-yes" : ""}`} aria-pressed={book.reread} onClick={() => onUpdateBook(book.id, { reread: !book.reread })}>{book.reread ? "Yes, in a heartbeat" : "Not sure yet"}<ChevronDown size={14}/></button></div><span className="pw-saved-note"><Check size={13}/>Saved as you write</span></section><section className="pw-panel"><div className="pw-panel-heading"><div><p className="pw-eyebrow">The feeling it left behind</p><h3>Little mood notes</h3></div><Sparkles size={17}/></div><TagEditor label="Moods" values={book.moods} onChange={(moods) => onUpdateBook(book.id, { moods })}/><TagEditor label="Tropes & moments" values={book.tropes} onChange={(tropes) => onUpdateBook(book.id, { tropes })}/><TagEditor label="Shelves" values={book.shelves} onChange={(shelves) => onUpdateBook(book.id, { shelves })}/></section><section className="pw-panel"><div className="pw-panel-heading"><div><p className="pw-eyebrow">The words you want to carry</p><h3>Favorite passages</h3></div><QuoteIcon size={17}/></div><form className="pw-inline-form pw-quote-add" onSubmit={addQuote}><Input aria-label="A passage you want to keep" placeholder="A line that stayed with you…" value={quoteText} onChange={(event) => setQuoteText(event.target.value)}/><Input aria-label="Page number" type="number" placeholder="Page" value={quotePage} onChange={(event) => setQuotePage(event.target.value)}/><Button type="submit" aria-label="Save passage"><Plus size={16}/></Button></form>{bookQuotes.length ? <div className="pw-book-quotes">{bookQuotes.map((quote) => <blockquote key={quote.id} className="pw-saved-quote"><QuoteIcon size={15}/><p>{quote.text}</p><span>{quote.page ? `Page ${quote.page} · ` : ""}{book.title}</span><button type="button" aria-label="Delete passage" onClick={() => onData({ ...data, quotes: data.quotes.filter((item) => item.id !== quote.id) })}><Trash2 size={14}/></button></blockquote>)}</div> : <p className="pw-soft-empty">A line worth keeping will always find a home here.</p>}</section><section className="pw-panel"><div className="pw-panel-heading"><div><p className="pw-eyebrow">Your own little annotations</p><h3>Chapter-by-chapter notes</h3></div><NotebookPen size={17}/></div><form className="pw-notes-form" onSubmit={addNote}><Input aria-label="Chapter" placeholder="Chapter, page or a little heading" value={noteChapter} onChange={(event) => setNoteChapter(event.target.value)}/><Textarea aria-label="Chapter note" placeholder="A thought for the margin…" value={noteText} onChange={(event) => setNoteText(event.target.value)}/><Button type="submit"><Plus size={15}/>Save a note</Button></form>{book.notes?.map((note, index) => <article className="pw-chapter-note" key={`${note.chapter}-${index}`}><span className="pw-handwritten">{note.chapter}</span><p>{note.text}</p><Button variant="ghost" size="icon" aria-label={`Delete note from ${note.chapter}`} onClick={() => onUpdateBook(book.id, { notes: (book.notes ?? []).filter((_, noteIndex) => noteIndex !== index) })}><Trash2 size={14}/></Button></article>)}</section><section className="pw-panel pw-listen-panel"><div className="pw-panel-heading"><div><p className="pw-eyebrow">A different way to hear the story</p><h3>Listen along</h3></div><Headphones size={18}/></div><div className="pw-search-inline"><Input type="url" aria-label="Spotify playlist or audiobook" placeholder="Spotify playlist, album, or audiobook link" value={book.spotify} onChange={(event) => onUpdateBook(book.id, { spotify: event.target.value })}/>{book.spotify && <a className="pw-player-link" href={spotifyEmbed(book.spotify)} target="_blank" rel="noreferrer" aria-label="Open in Spotify"><ExternalLink size={16}/></a>}</div>{book.spotify && (spotifyEmbed(book.spotify).includes("/embed/") ? <iframe className="pw-spotify-embed" src={spotifyEmbed(book.spotify)} title={`Spotify player for ${book.title}`} loading="lazy" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture"/> : <p className="pw-form-notice">Paste a Spotify link from open.spotify.com to show the player.</p>)}<span className="pw-saved-note"><Check size={13}/>Saved as you write</span></section></div></div><section className="pw-panel pw-session-history"><div className="pw-panel-heading"><div><p className="pw-eyebrow">Every visit counts</p><h3>Reading sessions</h3></div><span>{data.sessions.filter((session) => session.bookId === book.id).length} sessions</span></div>{data.sessions.filter((session) => session.bookId === book.id).length ? data.sessions.filter((session) => session.bookId === book.id).slice(0, 8).map((session) => <div className="pw-session-row" key={session.id}><CalendarDays size={15}/><strong>{shortDate(session.date)}</strong><span>{session.minutes} min</span><span>{session.pages} pages</span></div>) : <p className="pw-soft-empty">The next session in this story is yours to begin.</p>}</section></>;
}

function TagEditor({ label, values, onChange }: { label: string; values: string[]; onChange: (values: string[]) => void }) {
  const [draft, setDraft] = useState("");
  const submit = (event: FormEvent) => { event.preventDefault(); const value = draft.trim(); if (value && !values.some((item) => item.toLowerCase() === value.toLowerCase())) onChange([...values, value]); setDraft(""); };
  return <div className="pw-tag-field"><span className="pw-field-label">{label}</span><div className="pw-tags">{values.map((value, index) => <span className={`pw-tag pw-tag-${index % 4}`} key={value}>{value}<button type="button" aria-label={`Remove ${value}`} onClick={() => onChange(values.filter((item) => item !== value))}><X size={12}/></button></span>)}<form className="pw-tag-entry" onSubmit={submit}><Input aria-label={`Add ${label.toLowerCase()}`} placeholder={`Add ${label.toLowerCase()}…`} value={draft} onChange={(event) => setDraft(event.target.value)}/><button aria-label={`Add ${label.toLowerCase()}`} type="submit"><Plus size={13}/></button></form></div></div>;
}

function ShelvesView({ data, onData, onBook }: { data: ReadingData; onData: (data: ReadingData) => void; onBook: (id: string) => void }) {
  const [draft, setDraft] = useState(""); const [active, setActive] = useState("");
  const shelves = Array.from(new Set([...data.shelves, ...data.books.flatMap((book) => book.shelves)]));
  return <><PageIntro eyebrow="Stories, in their own little worlds" title="Your shelves" description="Gather your books into collections that feel like you."/><form className="pw-shelf-create" onSubmit={(event) => { event.preventDefault(); const name = draft.trim(); if (name && !shelves.includes(name)) onData({ ...data, shelves: [...data.shelves, name] }); setDraft(""); }}><label className="pw-search-inline"><Input aria-label="Name your new shelf" placeholder="Name a new shelf…" value={draft} onChange={(event) => setDraft(event.target.value)}/><Button type="submit"><Plus size={15}/>Make a shelf</Button></label></form><div className="pw-shelf-tabs"><button type="button" className={active === "" ? "pw-shelf-tab pw-shelf-tab-active" : "pw-shelf-tab"} onClick={() => setActive("")}>Every shelf <span>{data.books.length}</span></button>{shelves.map((shelf) => <button type="button" className={active === shelf ? "pw-shelf-tab pw-shelf-tab-active" : "pw-shelf-tab"} key={shelf} onClick={() => setActive(shelf)}>{shelf}<span>{data.books.filter((book) => book.shelves.includes(shelf)).length}</span></button>)}</div>{shelves.filter((shelf) => !active || active === shelf).map((shelf, index) => { const books = data.books.filter((book) => book.shelves.includes(shelf)); return <section className="pw-shelf-section" key={shelf}><div className="pw-shelf-banner"><span className={`pw-shelf-number pw-shelf-number-${index % 4}`}>{String(index + 1).padStart(2, "0")}</span><div><p className="pw-eyebrow">A collection of {books.length} {books.length === 1 ? "book" : "books"}</p><h3>{shelf}</h3></div><BookOpen size={21}/></div>{books.length ? <div className="pw-book-grid">{books.map((book) => <BookTile book={book} key={book.id} onClick={() => onBook(book.id)}/>)}</div> : <p className="pw-soft-empty">This shelf is ready for its first story.</p>}</section>; })}</>;
}

function GoalsView({ data, streak, onData, onBook }: { data: ReadingData; streak: number; onData: (data: ReadingData) => void; onBook: (id: string) => void }) {
  const finished = data.books.filter((book) => book.status === "Finished"); const pages = data.sessions.reduce((total, session) => total + session.pages, 0); const monthly = monthlyFinished(data); const annualProgress = Math.min(100, Math.round(finished.length / Math.max(1, data.annualGoal) * 100));
  const achievements = [{ name: "The very first", detail: "Finish your first book", unlocked: finished.length > 0, icon: BookOpen }, { name: "A lovely week", detail: "Read seven days in a row", unlocked: streak >= 7, icon: Flame }, { name: "A month of pages", detail: "Read thirty days in a row", unlocked: streak >= 30, icon: CalendarDays }, { name: "The ten-book year", detail: "Finish ten books this year", unlocked: finished.length >= 10, icon: Trophy }, { name: "Five shining stars", detail: "Give a book five stars", unlocked: finished.some((book) => book.rating === 5), icon: Star }, { name: "A whole new world", detail: "Finish a book in another genre", unlocked: new Set(finished.map((book) => book.genre)).size >= 4, icon: Sparkles }, { name: "Under the covers", detail: "Settle in for a reading session", unlocked: data.sessions.some((session) => session.minutes >= 30), icon: Moon }];
  return <><PageIntro eyebrow="Steady as she goes" title="A goal that feels like yours" description="Every story you finish is its own small celebration. Set a pace that fits your year."/><section className="pw-goal-hero pw-panel"><div className="pw-goal-big-ring"><GoalRing value={finished.length} total={data.annualGoal} label="books read"/><span>of your reading year</span></div><div className="pw-goal-hero-copy"><p className="pw-eyebrow">Your year, between the covers</p><h3>Every page is<br/>a small victory.</h3><p>You have read <strong>{finished.length}</strong> of your <strong>{data.annualGoal}-book goal</strong>. {Math.max(0, data.annualGoal - finished.length)} {data.annualGoal - finished.length === 1 ? "book remains" : "books remain"} — at your own sweet pace.</p><div className="pw-goal-inline-fields"><label>Yearly goal<input aria-label="Books in yearly reading goal" type="number" min="1" max="300" value={data.annualGoal} onChange={(event) => onData({ ...data, annualGoal: Math.max(1, Number(event.target.value) || 1) })}/><span>books</span></label><label>Monthly goal<input aria-label="Books in monthly reading goal" type="number" min="1" max="100" value={data.monthlyGoal} onChange={(event) => onData({ ...data, monthlyGoal: Math.max(1, Number(event.target.value) || 1) })}/><span>books</span></label><label>Pages goal<input aria-label="Pages in monthly reading goal" type="number" min="1" max="50000" value={data.pagesGoal} onChange={(event) => onData({ ...data, pagesGoal: Math.max(1, Number(event.target.value) || 1) })}/><span>pages</span></label></div></div><div className="pw-goal-motivation"><Flame size={18}/><strong>{streak || 1}</strong><span>day{streak === 1 ? "" : "s"} of making a little room for a story</span></div></section><div className="pw-goal-cards"><article className="pw-goal-small pw-panel"><div><span className="pw-mini-ring-mark"><BookMarked size={16}/></span><p className="pw-eyebrow">A few chapters each month</p><h3>This month</h3></div><GoalRing size="small" value={monthly} total={data.monthlyGoal} label="books"/><ProgressBar current={monthly} total={data.monthlyGoal}/></article><article className="pw-goal-small pw-panel"><div><span className="pw-mini-ring-mark pw-pages-mark"><BookOpen size={16}/></span><p className="pw-eyebrow">Let the pages take you somewhere</p><h3>Pages turned</h3></div><GoalRing size="small" value={Math.min(pages, data.pagesGoal)} total={data.pagesGoal} label="pages"/><ProgressBar current={pages} total={data.pagesGoal}/></article></div><section className="pw-panel pw-achievements"><SectionHeading eyebrow="Little things worth celebrating" title="The keepsakes you have earned"/><div className="pw-achievement-grid">{achievements.map(({ name, detail, unlocked, icon: Icon }) => <article key={name} className={`pw-achievement ${unlocked ? "pw-achievement-earned" : "pw-achievement-locked"}`}><span className="pw-achievement-icon"><Icon size={19}/></span><div><strong>{name}</strong><span>{detail}</span></div>{unlocked && <Check size={15}/>}</article>)}</div></section><section className="pw-panel pw-counted-books"><SectionHeading eyebrow="Every finished story counts" title="Read this year"/><div className="pw-finished-list">{finished.length ? finished.map((book) => <button type="button" key={book.id} className="pw-finished-row" onClick={() => onBook(book.id)}><Cover book={book} className="pw-finished-cover"/><span><strong>{book.title}</strong><small>{book.author} · Finished {shortDate(book.finished)}</small></span><span className="pw-stars"><Star size={12}/>{book.rating || "—"}</span><ArrowRight size={15}/></button>) : <p className="pw-soft-empty">Your next finished book is going to feel wonderful.</p>}</div><p className="pw-on-track"><TrendingUp size={15}/>{annualProgress >= 100 ? "You reached your goal. What a year of stories." : annualProgress > 0 ? "Looking good. Your reading year is coming together." : "A lovely goal, just waiting for its first story."}</p></section></>;
}

function QuotesView({ data, onData, onBook }: { data: ReadingData; onData: (data: ReadingData) => void; onBook: (id: string) => void }) {
  const [search, setSearch] = useState(""); const [draft, setDraft] = useState(""); const [bookId, setBookId] = useState(data.books[0]?.id ?? ""); const [pageNumber, setPageNumber] = useState("");
  const quotes = starterQuotes(data.quotes, data.books).filter((quote) => `${quote.text} ${quote.title} ${quote.author}`.toLowerCase().includes(search.toLowerCase()));
  return <><PageIntro eyebrow="The words you want to carry" title="Collected lines" description="A place for the words that stayed with you, long after the last page."/><form className="pw-quote-create pw-panel" onSubmit={(event) => { event.preventDefault(); if (!draft.trim() || !bookId) return; onData({ ...data, quotes: [{ id: makeId(), bookId, text: draft.trim(), page: Number(pageNumber) || 0, favorite: false }, ...data.quotes] }); setDraft(""); setPageNumber(""); toast.success("Those words have a place to live."); }}><span className="pw-quote-create-icon"><QuoteIcon size={19}/></span><label className="pw-field-label" htmlFor="pw-new-quote">Save a little piece of a story</label><Textarea id="pw-new-quote" aria-label="A quote to save" placeholder="A line, a thought, or a passage you want to remember…" value={draft} onChange={(event) => setDraft(event.target.value)}/><div className="pw-search-inline"><select className="pw-select" aria-label="Which book is this from" value={bookId} onChange={(event) => setBookId(event.target.value)}>{data.books.map((book) => <option key={book.id} value={book.id}>{book.title}</option>)}</select><Input type="number" aria-label="Page the quote appears on" placeholder="Page number" value={pageNumber} onChange={(event) => setPageNumber(event.target.value)}/><Button type="submit"><Plus size={15}/>Keep this line</Button></div></form><label className="pw-library-search pw-quote-search"><Search size={15}/><Input aria-label="Search your saved quotes" placeholder="Search your collected lines…" value={search} onChange={(event) => setSearch(event.target.value)}/></label>{quotes.length === 0 ? <EmptyState icon={QuoteIcon} title="No saved words on this shelf just yet"/> : <div className="pw-quotes-grid">{quotes.map((quote, index) => <article className={`pw-collected-quote pw-collected-quote-${index % 4}`} key={quote.id}><span className="pw-quote-open">“</span><p>{quote.text}</p><button type="button" className="pw-quote-book-link" onClick={() => onBook(quote.bookId)}>— {quote.title} {quote.page ? <span>· p. {quote.page}</span> : null}</button><div className="pw-quote-actions"><button type="button" onClick={() => { void navigator.clipboard?.writeText(quote.text).then(() => toast.success("Copied, just for you.")); }} aria-label="Copy quote"><NotebookPen size={15}/></button><button type="button" className={quote.favorite ? "pw-heart-active" : ""} onClick={() => onData({ ...data, quotes: data.quotes.map((item) => item.id === quote.id ? { ...item, favorite: !item.favorite } : item) })} aria-label={quote.favorite ? "Remove from favorites" : "Mark as a favorite"}><Heart size={16} fill={quote.favorite ? "currentColor" : "none"}/></button><button type="button" onClick={() => onData({ ...data, quotes: data.quotes.filter((item) => item.id !== quote.id) })} aria-label="Remove saved quote"><Trash2 size={15}/></button></div></article>)}</div>}</>;
}

function WishlistView({ data, onData, onBook }: { data: ReadingData; onData: (data: ReadingData) => void; onBook: (id: string) => void }) {
  const wishlist = data.books.filter((book) => book.status === "Want to read");
  const move = (book: Book) => { onData({ ...data, books: data.books.map((item) => item.id === book.id ? { ...item, status: "Reading" as const, started: new Date().toISOString().slice(0, 10) } : item) }); toast.success(`Here begins “${book.title}.”`); };
  const shift = (index: number, offset: number) => { const next = [...wishlist]; const destination = index + offset; if (destination < 0 || destination >= next.length) return; [next[index], next[destination]] = [next[destination]!, next[index]!]; let order = 0; const reordered = data.books.map((book) => book.status === "Want to read" ? (next[order++] ?? book) : book); onData({ ...data, books: reordered }); };
  return <><PageIntro eyebrow="For all the chapters ahead" title="A list of maybes" description="Books to dream about, take your time with, and one day bring home."/><div className="pw-wishlist-count"><Heart size={17}/><strong>{wishlist.length}</strong><span>stories waiting their turn</span></div>{wishlist.length === 0 ? <EmptyState icon={BookOpen} title="The future is wide open."/> : <div className="pw-wishlist-list">{wishlist.map((book, index) => <article className="pw-wishlist-item pw-panel" key={book.id}><span className="pw-queue-number">{String(index + 1).padStart(2, "0")}</span><Cover book={book} className="pw-wishlist-row-cover" onClick={() => onBook(book.id)}/><div className="pw-wishlist-copy"><p className="pw-eyebrow">{book.genre}</p><button type="button" className="pw-book-title pw-currently-title" onClick={() => onBook(book.id)}>{book.title}</button><span className="pw-reading-author">by {book.author}</span>{book.moods.length > 0 && <div className="pw-tags">{book.moods.map((mood, moodIndex) => <span key={mood} className={`pw-tag pw-tag-${moodIndex % 4}`}>{mood}</span>)}</div>}</div><div className="pw-queue-controls"><Button size="icon" variant="ghost" aria-label={`Move ${book.title} up`} disabled={index === 0} onClick={() => shift(index, -1)}><ChevronLeft className="pw-queue-up-icon"/></Button><Button size="icon" variant="ghost" aria-label={`Move ${book.title} down`} disabled={index === wishlist.length - 1} onClick={() => shift(index, 1)}><ChevronRight className="pw-queue-down-icon"/></Button></div><Button variant="outline" className="pw-begin-reading" onClick={() => move(book)}><BookOpen size={15}/>Begin this one</Button></article>)}</div>}<p className="pw-wishlist-note"><span className="pw-handwritten">No rush. The good ones wait.</span></p></>;
}

function StatsView({ data }: { data: ReadingData }) {
  const finished = data.books.filter((book) => book.status === "Finished"); const sessionsMinutes = data.sessions.reduce((sum, session) => sum + session.minutes, 0); const totalPages = data.sessions.reduce((sum, session) => sum + session.pages, 0); const avgRating = finished.length ? finished.reduce((sum, book) => sum + book.rating, 0) / finished.length : 0;
  const genres = new Map<string, number>(); finished.forEach((book) => genres.set(book.genre, (genres.get(book.genre) ?? 0) + 1)); const rated = new Map<number, number>([1, 2, 3, 4, 5].map((value) => [value, finished.filter((book) => book.rating === value).length])); const formatCounts = formats.reduce((all, format) => ({ ...all, [format]: data.books.filter((book) => book.format === format).length }), {} as Record<string, number>);
  const months = Array.from({ length: 6 }, (_, index) => { const now = new Date(); const month = new Date(now.getFullYear(), now.getMonth() - (5 - index), 1); const key = `${month.getFullYear()}-${String(month.getMonth() + 1).padStart(2, "0")}`; return { key, label: month.toLocaleDateString("en-US", { month: "short" }), pages: data.sessions.filter((session) => session.date.startsWith(key)).reduce((sum, session) => sum + session.pages, 0), books: finished.filter((book) => book.finished?.startsWith(key)).length }; });
  const maximum = Math.max(1, ...months.map((month) => month.pages)); const longest = [...data.books].sort((a, b) => b.pages - a.pages)[0];
  return <><PageIntro eyebrow="The shape of your reading" title="A life measured in pages" description="Your own small universe of stories, patterns, and new beginnings."/><div className="pw-stats-hero"><StatCard icon={BookOpenText} eyebrow="All the stories" value={data.books.length} note="Across all your shelves"/><StatCard icon={BookMarked} eyebrow="Pages turned" value={totalPages.toLocaleString()} note="Logged in your reading sessions" modifier="pw-stat-terracotta"/><StatCard icon={Clock3} eyebrow="Time well spent" value={`${Math.floor(sessionsMinutes / 60)}h ${sessionsMinutes % 60}m`} note="Enjoying a good book" modifier="pw-stat-gold"/><StatCard icon={Star} eyebrow="From the heart" value={avgRating ? avgRating.toFixed(1) : "—"} note="Average of finished ratings" modifier="pw-stat-ink"/></div><div className="pw-stats-chart-grid"><section className="pw-panel pw-chart-panel"><SectionHeading eyebrow="In six-month chapters" title="Pages you turned"/><div className="pw-bars-chart" aria-label="Pages read over the last six months">{months.map((month) => <div className="pw-bar-column" key={month.key}><span>{month.pages.toLocaleString()}<small> pages</small></span><div className="pw-bar-track"><span className="pw-bar-fill" style={{ height: `${Math.max(3, month.pages / maximum * 100)}%` }}/></div><small>{month.label}</small></div>)}</div><div className="pw-chart-caption"><TrendingUp size={15}/>A few pages at a time become a whole story.</div></section><section className="pw-panel pw-chart-panel"><SectionHeading eyebrow="Where the stories take you" title="Genres you love"/><div className="pw-genre-breakdown">{Array.from(genres.entries()).sort((a, b) => b[1] - a[1]).map(([genre, count], index) => <div key={genre} className="pw-genre-row"><span className={`pw-genre-dot pw-genre-dot-${index % 5}`}/><span>{genre}</span><div className="pw-genre-track"><span className={`pw-genre-fill pw-genre-fill-${index % 5}`} style={{ width: `${count / Math.max(1, finished.length) * 100}%` }}/></div><strong>{count}</strong></div>)}{genres.size === 0 && <p className="pw-soft-empty">A world of stories still waiting.</p>}</div></section><section className="pw-panel pw-chart-panel"><SectionHeading eyebrow="Every opinion counts" title="Your starry ratings"/>{[5, 4, 3, 2, 1].map((rating) => <div key={rating} className="pw-rating-row"><span>{rating} <Star size={12} fill="currentColor"/></span><div className="pw-rating-track"><span style={{ width: `${finished.length ? (rated.get(rating) ?? 0) / finished.length * 100 : 0}%` }}/></div><strong>{rated.get(rating) ?? 0}</strong></div>)}<p className="pw-chart-caption"><Star size={14}/>Your average: {avgRating ? avgRating.toFixed(1) : "—"} stars</p></section><section className="pw-panel pw-chart-panel"><SectionHeading eyebrow="Pages, in your preferred shape" title="How you like to read"/>{formats.map((format, index) => { const count = formatCounts[format] ?? 0; return <div key={format} className="pw-format-row"><span className={`pw-format-mark pw-format-mark-${index}`} aria-hidden="true">{format === "Audiobook" ? <Headphones size={16}/> : format === "Ebook" ? <AudioLines size={16}/> : <BookOpen size={16}/>}</span><span>{format}</span><div className="pw-genre-track"><span className={`pw-genre-fill pw-format-fill-${index}`} style={{ width: `${count / Math.max(1, data.books.length) * 100}%` }}/></div><strong>{count}</strong></div>; })}<p className="pw-chart-caption"><BookOpen size={14}/>{data.books.length} stories on the nightstand and beyond.</p></section></div><section className="pw-panel pw-stats-discovery"><span className="pw-stat-icon"><Sparkles size={19}/></span><div><p className="pw-eyebrow">The longest journey so far</p><h3>{longest?.title ?? "Every story counts"}</h3><p>{longest ? `${longest.pages} pages by ${longest.author}. A very fine place to get lost.` : "Your next story is waiting to be written."}</p></div><ArrowRight size={19}/></section></>;
}

function YearView({ data, streak }: { data: ReadingData; streak: number }) {
  const year = new Date().getFullYear(); const finished = data.books.filter((book) => book.status === "Finished" && (!book.finished || new Date(`${book.finished}T12:00:00`).getFullYear() === year));
  const pages = finished.reduce((sum, book) => sum + book.pages, 0); const genres = new Map<string, number>(); finished.forEach((book) => genres.set(book.genre, (genres.get(book.genre) ?? 0) + 1)); const favoriteGenre = [...genres].sort((a, b) => b[1] - a[1])[0]?.[0] ?? "A whole new world"; const topBook = [...finished].sort((a, b) => b.rating - a.rating)[0]; const monthCounts = new Map<string, number>(); finished.forEach((book) => { if (book.finished) { const month = new Date(`${book.finished}T12:00:00`).toLocaleDateString("en-US", { month: "long" }); monthCounts.set(month, (monthCounts.get(month) ?? 0) + 1); } }); const favoriteMonth = [...monthCounts].sort((a, b) => b[1] - a[1])[0]?.[0] ?? "The next chapter";
  return <div className="pw-wrapped"><section className="pw-wrapped-hero"><div className="pw-wrapped-stars" aria-hidden="true">✳　✶　✳　✵</div><p className="pw-eyebrow">A little look back at {year}</p><span className="pw-wrapped-wordmark">gildedpages</span><h2>A year held<br/>between the covers.</h2><p>The quiet moments. The turned pages. The stories that made their way home.</p><span className="pw-wrapped-year">YOUR READING RECAP · {year}</span></section><section className="pw-wrapped-stats"><article><span>Stories found their way to you</span><strong>{finished.length}</strong><small>finished and tucked away</small></article><article><span>Little worlds, one page at a time</span><strong>{pages.toLocaleString()}</strong><small>pages met along the way</small></article><article><span>A lovely day to remember</span><strong>{favoriteMonth}</strong><small>your biggest month of stories</small></article><article><span>Your favorite literary home</span><strong>{favoriteGenre}</strong><small>the stories that called your name</small></article><article><span>Your longest read, happily</span><strong className="pw-wrapped-top-book">{topBook?.title ?? "To be continued"}</strong><small>{topBook ? `${topBook.pages} pages by ${topBook.author}` : "A new story is on the horizon"}</small></article><article><span>Showing up for your stories</span><strong>{streak} {streak === 1 ? "day" : "days"}</strong><small>your current reading streak</small></article></section><section className="pw-panel pw-year-books"><SectionHeading eyebrow="A shelf full of memories" title={`The stories you met in ${year}`}/><div className="pw-year-covers">{finished.map((book) => <BookTile key={book.id} book={book} compact onClick={() => { window.location.assign(`/book/${book.id}`); }}/>)}</div></section><div className="pw-wrapped-actions"><span className="pw-handwritten">A whole year of wonder. Keep it close.</span><Button onClick={() => window.print()}><Share2 size={16}/>Print or share this year</Button></div></div>;
}

function SettingsView({ data, onData }: { data: ReadingData; onData: (data: ReadingData) => void }) {
  const importRef = useRef<HTMLInputElement>(null);
  const updateLink = (key: keyof ReadingData["links"], value: string) => onData({ ...data, links: { ...data.links, [key]: value } });
  const exportData = () => { const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }); const href = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = href; anchor.download = `gildedpages-journal-${new Date().toISOString().slice(0, 10)}.json`; anchor.click(); URL.revokeObjectURL(href); toast.success("Your journal is safely in your downloads."); };
  const importData = async (file: File | undefined) => { if (!file) return; try { const incoming = JSON.parse(await file.text()) as Partial<ReadingData>; if (!Array.isArray(incoming.books) || !Array.isArray(incoming.quotes) || !Array.isArray(incoming.sessions)) throw new Error("This file doesn't look like a Gilded Pages journal."); onData({ ...DEMO_DATA, ...incoming, books: incoming.books, quotes: incoming.quotes, sessions: incoming.sessions }); toast.success("Your reading journal is back on the shelf."); } catch (error) { toast.error(error instanceof Error ? error.message : "This journal couldn't be opened."); } finally { if (importRef.current) importRef.current.value = ""; } };
  return <><PageIntro eyebrow="A place that feels like you" title="Your little corner" description="A few simple choices to make your reading journal your own."/><section className="pw-settings-section"><div className="pw-settings-heading"><span className="pw-settings-icon"><NotebookPen size={17}/></span><div><h3>Who is turning the pages?</h3><p>A name to greet you when you come home.</p></div></div><label className="pw-settings-input"><span>Your name</span><Input aria-label="Your reader name" value={data.name} maxLength={40} onChange={(event) => onData({ ...data, name: event.target.value })}/></label></section><section className="pw-settings-section"><div className="pw-settings-heading"><span className="pw-settings-icon"><Trophy size={17}/></span><div><h3>Gentle reading goals</h3><p>Ambitious enough to inspire. Gentle enough to feel good.</p></div></div><div className="pw-settings-goals"><label>Books in your year<input aria-label="Yearly reading book goal" type="number" min="1" max="300" value={data.annualGoal} onChange={(event) => onData({ ...data, annualGoal: Math.max(1, Number(event.target.value) || 1) })}/></label><label>Books in a month<input aria-label="Monthly reading goal" type="number" min="1" max="100" value={data.monthlyGoal} onChange={(event) => onData({ ...data, monthlyGoal: Math.max(1, Number(event.target.value) || 1) })}/></label><label>Pages in a month<input aria-label="Monthly page goal" type="number" min="1" max="50000" value={data.pagesGoal} onChange={(event) => onData({ ...data, pagesGoal: Math.max(1, Number(event.target.value) || 1) })}/></label></div></section><section className="pw-settings-section"><div className="pw-settings-heading"><span className="pw-settings-icon">{data.darkMode ? <Moon size={17}/> : <Sun size={17}/>}</span><div><h3>Make it evening or daylight</h3><p>A reading room for any hour of the day.</p></div></div><button type="button" className="pw-setting-toggle" onClick={() => onData({ ...data, darkMode: !data.darkMode })}><span>{data.darkMode ? "Evening pages" : "Daylight pages"}</span><span className={`pw-toggle-track ${data.darkMode ? "pw-toggle-on" : ""}`}><span/></span></button></section><section className="pw-settings-section"><div className="pw-settings-heading"><span className="pw-settings-icon"><BookOpen size={17}/></span><div><h3>Your reading size</h3><p>A little larger or smaller, just how you like it.</p></div></div><div className="pw-view-toggle pw-font-size-toggle" aria-label="Text size">{(["small", "medium", "large"] as const).map((size) => <button type="button" key={size} onClick={() => onData({ ...data, fontSize: size })} aria-pressed={data.fontSize === size} className={data.fontSize === size ? "pw-view-active" : ""}>{size === "small" ? "A" : size === "medium" ? "A A" : "A A A"}</button>)}</div></section><section className="pw-settings-section"><div className="pw-settings-heading"><span className="pw-settings-icon"><Music2 size={17}/></span><div><h3>A soundtrack for your reading</h3><p>Your own listening companion, linked from Spotify.</p></div></div><label className="pw-settings-input"><span>Spotify playlist link</span><Input type="url" aria-label="Your Spotify playlist link" placeholder="https://open.spotify.com/playlist/…" value={data.spotify} onChange={(event) => onData({ ...data, spotify: event.target.value })}/></label>{data.spotify && (spotifyEmbed(data.spotify).includes("/embed/") ? <iframe className="pw-spotify-embed pw-settings-spotify" src={spotifyEmbed(data.spotify)} title="Your reading playlist" loading="lazy" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture"/> : <p className="pw-form-notice">Use a Spotify link from open.spotify.com to preview your playlist.</p>)}</section><section className="pw-settings-section"><div className="pw-settings-heading"><span className="pw-settings-icon"><ExternalLink size={17}/></span><div><h3>Your other reading rooms</h3><p>Goodreads, StoryGraph, and the local library.</p></div></div><div className="pw-settings-goals pw-quicklink-settings">{([["goodreads", "Goodreads"], ["storygraph", "StoryGraph"], ["library", "Local library"]] as const).map(([key, label]) => <label key={key}>{label}<input aria-label={`${label} link`} type="url" placeholder="https://…" value={data.links[key]} onChange={(event) => updateLink(key, event.target.value)}/></label>)}</div></section><section className="pw-settings-section"><div className="pw-settings-heading"><span className="pw-settings-icon"><Download size={17}/></span><div><h3>Carry your journal with you</h3><p>Save a copy or bring your journal home on another device.</p></div></div><div className="pw-settings-data-actions"><Button variant="outline" onClick={exportData}><Download size={15}/>Save a copy</Button><Button variant="outline" onClick={() => importRef.current?.click()}><FileUp size={15}/>Open a saved copy</Button><input type="file" accept="application/json,.json" ref={importRef} className="pw-visually-hidden" onChange={(event) => void importData(event.target.files?.[0])}/></div></section><section className="pw-settings-section pw-settings-reset"><div className="pw-settings-heading"><span className="pw-settings-icon"><ArrowDownWideNarrow size={17}/></span><div><h3>Start fresh</h3><p>Replace this journal with the original sample books and reading history.</p></div></div><Button variant="outline" className="pw-reset-button" onClick={() => { if (window.confirm("Replace your journal with the original Gilded Pages sample books? Your current books and notes will be removed.")) { onData({ ...DEMO_DATA, sessions: DEMO_DATA.sessions.map((session) => ({ ...session })), quotes: DEMO_DATA.quotes.map((quote) => ({ ...quote })), books: DEMO_DATA.books.map((book) => ({ ...book, notes: [] })) }); toast.success("A fresh reading journal, ready for a new chapter."); } }}><Trash2 size={15}/>Reset sample journal</Button></section><SignOutSection/></>;
}

function QuickLinks({ data, onData }: { data: ReadingData; onData: (data: ReadingData) => void }) {
  return <div className="pw-quick-links"><span>Other favorite shelves</span>{([["goodreads", "Goodreads"], ["storygraph", "StoryGraph"], ["library", "Your local library"]] as const).map(([key, label]) => <label key={key}>{data.links[key] ? <a href={data.links[key]} target="_blank" rel="noreferrer">{label}<ExternalLink size={13}/></a> : <button type="button" onClick={() => { const link = window.prompt(`Paste your ${label} link`); if (link?.trim()) onData({ ...data, links: { ...data.links, [key]: link.trim() } }); }}>{label}<Plus size={12}/></button>}</label>)}</div>;
}
function spotifyEmbed(value: string) {
  try {
    const url = new URL(value.trim()); if (!url.hostname.endsWith("spotify.com")) return "";
    url.hostname = "open.spotify.com"; url.pathname = url.pathname.replace(/^\/(embed\/)?/, "/embed/").replace(/\/$/, ""); return url.toString();
  } catch { return ""; }
}
function TimerDialog({ book, onClose, onSave }: { book: Book | null; onClose: () => void; onSave: (bookId: string, minutes: number, pages: number) => void }) {
  const [seconds, setSeconds] = useState(0); const [running, setRunning] = useState(false); const [pageCount, setPageCount] = useState(0); const [finished, setFinished] = useState(false);
  useEffect(() => { if (!running) return; const timer = window.setInterval(() => setSeconds((value) => value + 1), 1000); return () => window.clearInterval(timer); }, [running]);
  useEffect(() => { if (book) { setSeconds(0); setRunning(false); setPageCount(0); setFinished(false); } }, [book?.id]);
  if (!book) return null;
  const minutes = Math.round(seconds / 60); const clock = `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
  return <div className="pw-modal-backdrop" role="presentation" onClick={(event) => { if (event.target === event.currentTarget) { setRunning(false); onClose(); } }}><section className="pw-modal pw-timer-modal" role="dialog" aria-modal="true" aria-labelledby="pw-timer-title"><div className="pw-modal-heading"><span className="pw-modal-icon"><Timer size={21}/></span><div><p className="pw-eyebrow">A moment for your book</p><h2 id="pw-timer-title">Settle in with it</h2><p>{book.title} · {book.author}</p></div><Button variant="ghost" size="icon" aria-label="Close reading timer" onClick={() => { setRunning(false); onClose(); }}><X/></Button></div><div className="pw-timer-clock"><span className="pw-handwritten">just you and the page</span><strong>{clock}</strong><span>{running ? "A lovely little reading session, in progress." : finished ? "A little piece of quiet, well spent." : "No rush. Start when you are ready."}</span></div><label className="pw-timer-pages"><span>How many pages did you read?</span><input aria-label="Pages read in this session" type="number" min="0" max={book.pages} value={pageCount} onChange={(event) => setPageCount(Math.max(0, Number(event.target.value) || 0))}/></label><div className="pw-timer-actions">{!finished ? <><Button onClick={() => { if (running) setRunning(false); else { setFinished(false); setRunning(true); } }}>{running ? <><Pause size={16}/>Take a pause</> : <><Play size={16}/>Begin reading</>}</Button>{seconds > 0 && <Button variant="outline" onClick={() => { setRunning(false); setFinished(true); }}><Check size={16}/>Finish this session</Button>}</> : <Button onClick={() => { setRunning(false); onSave(book.id, Math.max(1, minutes), pageCount); onClose(); }}><Check size={16}/>Save my reading session</Button>}</div><p className="pw-timer-note"><Flame size={13}/>A session adds to your reading history and daily calendar.</p></section></div>;
}

function SignOutSection() {
  const { user, signOut } = useAuth();
  const navigate = useNavigate();
  return (
    <section className="pw-settings-section pw-settings-reset">
      <div className="pw-settings-heading">
        <span className="pw-settings-icon"><LogOut size={17}/></span>
        <div><h3>Your account</h3><p>Signed in as {user?.email ?? "you"}.</p></div>
      </div>
      <Button variant="outline" className="pw-reset-button" onClick={() => { void signOut().then(() => navigate({ to: "/login" })); }}><LogOut size={15}/>Sign out</Button>
    </section>
  );
}
